class Solution {
    fun solution(babbling: Array<String>): Int {
        var answer: Int = 0
        val a = arrayOf("aya", "ye", "woo", "ma")

        for(i in babbling){
            var word = i
            for (j in a) {
                word = word.replace(j, " ")
            }
            if (word.replace(" ", "").isEmpty()) {
                answer++
            }
        }
        return answer
    }
}

class Solution {
    fun solution(dots: Array<IntArray>): Int {

        val x1 = dots[0][0]
        val y1 = dots[0][1]
        val x2 = dots[1][0]
        val y2 = dots[1][1]
        val x3 = dots[2][0]
        val y3 = dots[2][1]
        val x4 = dots[3][0]
        val y4 = dots[3][1]

        var a = (y1-y2)*(x3-x4)
        if (a<0) a = a * ( -1 )

        var b = (x1-x2)*(y3-y4)
        if (b<0) b = b * ( -1 )

        if(a==b) return 1

        var c = (y1-y3)*(x2-x4)
        if (c<0) c = c * ( -1 )

        var d = (x1-x3)*(y2-y4)
        if (d<0) d = d * ( -1 )

        if(c==d) return 1

        var e = (y1-y4)*(x2-x3)
        if (e<0) e = e * ( -1 )

        var f = (x1-x4)*(y2-y3)
        if (f<0) f = f * ( -1 )

        if(e==f) return 1

        return 0
    }
}
